import { togglePublicSharingV2 } from '~/client';
import type { TogglePublicSharingResponse, PublicLinkType } from '~/client';

export const useToggleProjectPublicLink = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (data: {
      projectId: string;
      enabled: boolean;
      type: PublicLinkType;
    }): Promise<TogglePublicSharingResponse> =>
      togglePublicSharingV2({
        composable: '$fetch',
        path: { link_type: data.type, project_id: data.projectId },
        body: { enabled: data.enabled },
      }),
    onMutate: (data) => {
      queryCache.setQueryData(
        [`${data.type}.public-link`, data.projectId, data.type],
        (oldData?: TogglePublicSharingResponse) => {
          return {
            ...oldData,
            enabled: data.enabled,
          };
        }
      );
    },
    onSuccess: async (_, data) => {
      showToastSuccess(
        `${data.type === 'dashboard' ? 'Dashboard' : 'Project'} public link was ${data.enabled ? 'enabled' : 'disabled'} successfully`
      );
    },
    onError(error, data) {
      showToastError(error);
      queryCache.setQueryData(
        [`${data.type}.public-link`, data.projectId, data.type],
        (oldData?: TogglePublicSharingResponse) => {
          return {
            ...oldData,
            enabled: !data.enabled,
          };
        }
      );
    },
  });

  return {
    toggleProjectPublicLink: mutateAsync,
    isToggleProjectPublicLinkLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
