<template>
  <Dialog>
    <DialogTrigger as-child>
      <slot>
        <Button variant="outline" :prepend-icon="Share2Icon">Share</Button>
      </slot>
    </DialogTrigger>
    <DialogContent class="sm:max-w-[425px]">
      <DialogHeader>
        <DialogTitle>Share {{ subject }}</DialogTitle>
        <DialogDescription v-if="!isLoading">
          This {{ subject === 'details' ? 'project details are' : 'dashboard is' }} publicly available via this link
        </DialogDescription>
      </DialogHeader>
      <div class="flex flex-col gap-2">
        <AppLoader v-if="isLoading" variant="inline" :subject="`${subject} public link`" />
        <AppError
          v-else-if="error"
          variant="table"
          :error="error"
          :title="`Failed to load ${subject === 'details' ? 'project' : 'dashboard'} link`"
          action-text="Retry"
          :action="refetch"
        />
        <template v-else>
          <div class="flex items-center gap-2">
            <Switch
              id="enable-state"
              v-model="isLinkEnabled"
              @update:model-value="
                async (value) => {
                  await toggleProjectPublicLink({
                    projectId,
                    enabled: value,
                    type: subject,
                  });
                }
              "
            >
              <template #thumb>
                <Spinner v-if="isToggleProjectPublicLinkLoading" class="w-5 h-5 fill-foreground" />
              </template>
            </Switch>
            <Label v-if="!isToggleProjectPublicLinkLoading" for="enable-state"
              >Link {{ isLinkEnabled ? 'Enabled' : 'Disabled' }}</Label
            >
            <template v-else>
              <Label v-if="isLinkEnabled">Disabling link</Label>
              <Label v-else>Enabling link</Label>
            </template>
          </div>
          <div class="flex flex-row gap-2">
            <div class="relative w-full max-w-sm items-center">
              <span class="absolute start-0 inset-y-0 flex items-center justify-center px-2">
                <EarthIcon class="size-6 text-muted-foreground" />
              </span>
              <Input id="public_link" type="text" placeholder="Public link" class="pl-10" :model-value="publicUrl" />
            </div>
            <CopyButton :value="publicUrl" />
          </div>
        </template>
      </div>
    </DialogContent>
  </Dialog>
</template>
<script setup lang="ts">
import { EarthIcon, Share2Icon } from 'lucide-vue-next';
import { useToggleProjectPublicLink } from '~/mutations/project/public_link/toggle';
import { Spinner } from '~/assets/icons';
import { getProjectPublicLinkV2, type PublicLinkType } from '~/client';

interface Props {
  subject: PublicLinkType;
}

const props = defineProps<Props>();

const route = useRoute('projects-id');
const projectId = computed(() => route.params.id as string);

const {
  data: projectPublicLink,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => [`${props.subject}.public-link`, projectId.value, props.subject],
  query: () =>
    getProjectPublicLinkV2({ composable: '$fetch', path: { project_id: projectId.value, link_type: props.subject } }),
  enabled: () => !!projectId.value || !!props.subject,
});

const publicUrl = computed(() => projectPublicLink.value?.url);

const { toggleProjectPublicLink, isToggleProjectPublicLinkLoading } = useToggleProjectPublicLink();

const isLinkEnabled = computed({
  get() {
    return projectPublicLink.value?.enabled;
  },
  set(value) {},
});
</script>
